<div class="mb-8"><div class="text-sm text-gray-500">Discovery configuration</div><h1 class="display text-4xl font-bold">Sources</h1></div><div class="grid lg:grid-cols-2 gap-6"><form method="post" action="/admin/sources/save" class="bg-white rounded-2xl shadow-sm p-6 space-y-4"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input required name="name" placeholder="Source name" class="w-full rounded-lg border border-gray-200 px-3 py-2"><input name="website_url" placeholder="Website URL" class="w-full rounded-lg border border-gray-200 px-3 py-2"><input required name="rss_url" placeholder="RSS URL" class="w-full rounded-lg border border-gray-200 px-3 py-2"><select name="category_id" class="w-full rounded-lg border border-gray-200 px-3 py-2"><option value="">No category</option><?php foreach($categories as $c): ?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach; ?></select><label class="text-sm"><input type="checkbox" name="active" checked> Active source</label><button class="rounded-lg bg-[#101513] text-white py-3 px-5 font-semibold">Add source</button></form><div class="bg-white rounded-2xl shadow-sm divide-y"><?php foreach($sources as $s): ?><div class="p-5 flex justify-between gap-4"><div><div class="font-semibold"><?=e($s['name'])?></div><div class="text-xs text-gray-500 mt-1"><?=e($s['rss_url'])?> · <?=e($s['category_name']??'Uncategorized')?> · <?=$s['active']?'Active':'Inactive'?></div></div><form method="post" action="/admin/sources/toggle"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$s['id']?>"><button class="text-sm underline"><?=$s['active']?'Disable':'Enable'?></button></form></div><?php endforeach; ?></div></div>
